{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_ecf1e540ff20383100a1b4f3", "claim_ids": ["claim_0b9a4947d610fabe8cb16e8a", "claim_a47944e846150842f118fd1d"], "query_ids": ["q_346"], "claims": [{"claim_id": "claim_0b9a4947d610fabe8cb16e8a", "quote": "Section 232 Auto & Auto Parts Duties and Reciprocal Tariffs | Normal Duty + 25% (auto & auto parts only)", "url": "https://www.internationaltradeinsights.com/2025/08/summary-of-tariff-requirements-updated-august-4-2025", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 Auto & Auto Parts Duties and Reciprocal Tariffs", "duty_rate": "Normal Duty + 25%", "effective_date": "March 4, 2025"}}, {"claim_id": "claim_a47944e846150842f118fd1d", "quote": "Tariffs were increased to 35% effective August 1, 2025", "url": "https://www.internationaltradeinsights.com/2025/08/summary-of-tariff-requirements-updated-august-4-2025", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 Auto & Auto Parts Duties and IEEPA Tariffs (Canada & Mexico)", "duty_rate": "35%", "effective_date": "August 1, 2025"}}]}, {"pair_id": "conflict_36707a68d78c1e85c9490bce", "claim_ids": ["claim_a7f7b6c66c7259c467822e1d", "claim_c07265f9a89e128019908a17"], "query_ids": ["q_346"], "claims": [{"claim_id": "claim_a7f7b6c66c7259c467822e1d", "quote": "On March 26, the President issued a Proclamation imposing a tariff of 25% on imports of automobiles effective April 3, with a tariff of 25% also on imports of auto parts effective May 3.", "url": "https://www.cov.com/en/news-and-insights/insights/2025/07/status-of-section-232-actions-by-the-trump-administration", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "affected_product": "imports of auto parts", "duty_rate": "25%", "effective_date": "May 3"}}, {"claim_id": "claim_c07265f9a89e128019908a17", "quote": "On March 26, the President issued a Proclamation imposing a tariff of 25% on imports of automobiles effective April 3, with a tariff of 25% also on imports of auto parts effective May 3.", "url": "https://www.cov.com/en/news-and-insights/insights/2025/07/status-of-section-232-actions-by-the-trump-administration", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "affected_product": "imports of automobiles", "duty_rate": "25%", "effective_date": "April 3"}}]}, {"pair_id": "conflict_e005fe739022279f84bd8fed", "claim_ids": ["claim_1ee321bbaf82a57811f24908", "claim_4fdff70940017a274acab875"], "query_ids": ["q_347"], "claims": [{"claim_id": "claim_1ee321bbaf82a57811f24908", "quote": "President Trump announced tariffs of 50% will take effect August 1, though no formal proclamation or notice to this effect has yet been issued.", "url": "https://www.cov.com/en/news-and-insights/insights/2025/07/status-of-section-232-actions-by-the-trump-administration", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "effective_date": "August 1"}}, {"claim_id": "claim_4fdff70940017a274acab875", "quote": "Tariffs were paused until March 4, 2025 and went into effect on March 4, 2025", "url": "https://www.internationaltradeinsights.com/2025/08/summary-of-tariff-requirements-updated-august-4-2025", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 Auto & Auto Parts Duties and IEEPA Tariffs (Canada & Mexico)", "effective_date": "March 4, 2025"}}]}, {"pair_id": "conflict_d543ae0689e176fccb4727c1", "claim_ids": ["claim_4fdff70940017a274acab875", "claim_a47944e846150842f118fd1d"], "query_ids": ["q_347"], "claims": [{"claim_id": "claim_4fdff70940017a274acab875", "quote": "Tariffs were paused until March 4, 2025 and went into effect on March 4, 2025", "url": "https://www.internationaltradeinsights.com/2025/08/summary-of-tariff-requirements-updated-august-4-2025", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 Auto & Auto Parts Duties and IEEPA Tariffs (Canada & Mexico)", "effective_date": "March 4, 2025"}}, {"claim_id": "claim_a47944e846150842f118fd1d", "quote": "Tariffs were increased to 35% effective August 1, 2025", "url": "https://www.internationaltradeinsights.com/2025/08/summary-of-tariff-requirements-updated-august-4-2025", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 Auto & Auto Parts Duties and IEEPA Tariffs (Canada & Mexico)", "duty_rate": "35%", "effective_date": "August 1, 2025"}}]}, {"pair_id": "conflict_0f1348220bf226182098baf6", "claim_ids": ["claim_1b62fd2f35bee284c78f94c7", "claim_b3bbba564a7fb8cc3c27c3ac"], "query_ids": ["q_348"], "claims": [{"claim_id": "claim_1b62fd2f35bee284c78f94c7", "quote": "starting at 12:01 a.m. Eastern Time on August 18, 2025, 407 new steel and aluminum derivative products will be subject to the existing 50% Section 232 tariffs", "url": "https://www.ghy.com/trade-compliance/50-section-232-tariffs-on-407-new-steel-and-aluminum-derivatives-take-effect-aug-18-cbp-guidance-available", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "50%", "effective_date": "August 18, 2025", "reported_policy_status": "Take Effect"}}, {"claim_id": "claim_b3bbba564a7fb8cc3c27c3ac", "quote": "Effective with respect to goods entered for consumption, or withdrawn from warehouse for consumption, on or after 12:01 a.m. eastern daylight time on August 18, 2025, subchapter III of chapter 99 of the Harmonized Tariff Schedule of the United States (HTSUS) is modified", "url": "https://www.federalregister.gov/documents/2025/08/19/2025-15819/adoption-and-procedures-of-the-section-232-steel-and-aluminum-tariff-inclusions-process", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "subchapter III of chapter 99 of the Harmonized Tariff Schedule of the United States (HTSUS)", "effective_date": "August 18, 2025", "reported_policy_status": "modified"}}]}, {"pair_id": "conflict_519823f21900d70999880769", "claim_ids": ["claim_0121e6ff87fc85fedb29ce21", "claim_ecdb323af65c84a1823af870"], "query_ids": ["q_35"], "claims": [{"claim_id": "claim_0121e6ff87fc85fedb29ce21", "quote": "Georgia Hyundai Battery Plant", "url": "https://www.reddit.com/r/Ioniq5/comments/1jse6v5/hyundai_avoiding_tariffs_with_agreement_with_the", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "facility": "Georgia Hyundai Battery Plant"}}, {"claim_id": "claim_ecdb323af65c84a1823af870", "quote": "On Wednesday, Hyundai Motor is set to hold an opening ceremony for a new $7.59bn car and battery factory in Georgia.", "url": "https://www.bbc.com/news/articles/cgkmvdz144vo", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai Motor", "facility": "new $7.59bn car and battery factory", "tariff_program": "Trump tariffs"}}]}, {"pair_id": "conflict_3b9cd9872db1db6bb4348b50", "claim_ids": ["claim_1474b637357d6403f149154f", "claim_197d39f2f4ff022f1e1bacea"], "query_ids": ["q_350"], "claims": [{"claim_id": "claim_1474b637357d6403f149154f", "quote": "Effective with respect to goods entered for consumption, or withdrawn from warehouse for consumption, on or after 12:01 a.m. eastern daylight time on August 18, 2025, subchapter III of chapter 99 of the Harmonized Tariff Schedule of the United States (HTSUS) is modified:", "url": "https://www.federalregister.gov/documents/2025/08/19/2025-15819/adoption-and-procedures-of-the-section-232-steel-and-aluminum-tariff-inclusions-process", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "subchapter III of chapter 99 of the Harmonized Tariff Schedule of the United States (HTSUS)", "effective_date": "August 18, 2025", "reported_policy_status": "modified"}}, {"claim_id": "claim_197d39f2f4ff022f1e1bacea", "quote": "Effective with respect to goods entered for consumption, or withdrawn from warehouse for consumption, on or after 12:01 a.m. eastern daylight time on July 1, 2025, subchapter III of chapter 99 of the HTSUS is modified:", "url": "https://www.federalregister.gov/documents/2025/08/19/2025-15819/adoption-and-procedures-of-the-section-232-steel-and-aluminum-tariff-inclusions-process", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "subchapter III of chapter 99 of the HTSUS", "effective_date": "July 1, 2025"}}]}, {"pair_id": "conflict_bf29ff453056151e63049812", "claim_ids": ["claim_3e071a8e805edd096e820e36", "claim_b56d0ebea19a852848024f58"], "query_ids": ["q_351"], "claims": [{"claim_id": "claim_3e071a8e805edd096e820e36", "quote": "Under the new order, all imports of steel and aluminum will be subject to a 25% tariff rate, effective March 12, 2025. This represents an increase from the previous 10% tariff on aluminum.", "url": "https://www.autocare.org/government-relations/current-issues/tariffs-and-trade/section-232-steel-aluminum-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%", "effective_date": "March 12, 2025"}}, {"claim_id": "claim_b56d0ebea19a852848024f58", "quote": "A White House Proclamation lifted Section 232 to 50% for most countries; United Kingdom 25%. For Chapter 73 (steel) and Chapter 76 (aluminum) articles, the Proclamation confirms the ad-valorem duty “apply[ies] only to the steel content” or “only to the aluminum content.” Proclamation, 3 Jun 2025.", "url": "https://globaltradealert.org/reports/Section-232-Metal-Content-Calculus-Explained", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "50%"}}]}, {"pair_id": "conflict_0808b795c6709c5df0893e28", "claim_ids": ["claim_3e7cd664ba77e5f59365b4b0", "claim_c7a4c35a58f16c74424ecc4a"], "query_ids": ["q_351"], "claims": [{"claim_id": "claim_3e7cd664ba77e5f59365b4b0", "quote": "CBP ties the metal-content value to the standard customs valuation law, 19 U.S.C. § 1401a, i.e. “the total price paid or payable” for the steel/aluminum input—“normally … based on the invoice” for that input (exclusive of international freight/insurance).", "url": "https://globaltradealert.org/reports/Section-232-Metal-Content-Calculus-Explained", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_c7a4c35a58f16c74424ecc4a", "quote": "If the value of the [metal] content … is unknown, the duty must be reported … based on the entire entered value” (one line). See CSMS 3 Jun 2025 for steel and aluminum: Aluminum • Steel.", "url": "https://globaltradealert.org/reports/Section-232-Metal-Content-Calculus-Explained", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_7caf4e2b49e277d7b605ed0e", "claim_ids": ["claim_3052010aa31825d1acca7530", "claim_9c8dbe3ef1c409464abe5d27"], "query_ids": ["q_352"], "claims": [{"claim_id": "claim_3052010aa31825d1acca7530", "quote": "Tariffs of 25% to be imposed on additional steel derivatives and aluminum derivatives. The additional duty shall only apply to the declared value of the aluminum or stel content of the derivative article.", "url": "https://www.autocare.org/government-relations/current-issues/tariffs-and-trade/section-232-steel-aluminum-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "additional steel derivatives and aluminum derivatives"}}, {"claim_id": "claim_9c8dbe3ef1c409464abe5d27", "quote": "On February 18, 2025, two Federal Register Notices were published that included lists of “derivative” steel and aluminum products subject to the 25% tariffs on steel and aluminum under Section 232.", "url": "https://diaztradelaw.com/section-232-valuation-in-a-gray-area-what-importers-need-to-know", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "announcement_date": "February 18, 2025", "effective_date": "June 4, 2025"}}]}]}

